<?php /** @var \Sysfera\Plugin $sf @var string $tab @var array $o @var array $items @var ?array $code @var ?array $wh @var array $incidents @var array $log */
include __DIR__ . '/_nav.php'; $next = \SysferaGi\Machine::next($o['status']); ?>
<div class="page-h"><h1>#<?= e($o['number']) ?> <span class="gi-st gi-<?= e($o['status']) ?>"><?= e($sf->t('st_' . $o['status'])) ?></span></h1><a class="btn" href="<?= e($sf->url('/transfers/' . $o['transfer_uuid'])) ?>">← <?= e($sf->t('transfer')) ?></a></div>
<div class="card"><p><b><?= e($o['customer_name']) ?></b> <?= e($o['customer_phone']) ?> <?= e($o['customer_email'] ?? '') ?></p>
  <p><?= e($sf->t('warehouse')) ?>: <?= e($wh['name'] ?? '?') ?> · <?= e($sf->t('total')) ?>: <b><?= e($o['total_rub']) ?> ₽</b> · v<?= (int)$o['version'] ?><?= $o['issued_at'] ? ' · ' . e($sf->t('issued_at')) . ' ' . e($o['issued_at']) : '' ?></p>
  <?php if (!empty($o['shelf'])): ?><p><?= e($sf->t('shelf')) ?>: <b><?= e($o['shelf']) ?></b></p><?php endif; ?>
  <?php if (($o['handover'] ?? '') === 'courier'): $cr = json_decode((string)$o['courier'], true) ?: []; ?><p><span class="gi-sev gi-sev-medium"><?= e($sf->t('handover_courier')) ?></span> <?= e(strtoupper((string)($cr['service'] ?? ''))) ?> · <?= e($cr['name'] ?? '') ?> · <code><?= e($cr['waybill'] ?? '') ?></code></p><?php endif; ?>
  <?php if (!empty($act)): $ap = json_decode((string)$act['payload'], true) ?: []; ?><p><?= e($sf->t('evidence')) ?>: <?php if (!empty($ap['evidence_sha256'])): ?><a href="<?= e($sf->url('/evidence/' . $act['uuid'] . '/signature')) ?>" target="_blank"><?= e($sf->t('ev_signature')) ?></a><?php endif; ?>
    <?php if (!empty($ap['photo_sha256'])): ?> · <a href="<?= e($sf->url('/evidence/' . $act['uuid'] . '/photo')) ?>" target="_blank"><?= e($sf->t('ev_photo')) ?></a><?php endif; ?></p><?php endif; ?>
  <?php foreach ($returns ?? [] as $r): $rd = $r['data']; ?><p><a href="<?= e($sf->url('/returns')) ?>"><?= e($sf->t('nav_returns')) ?></a>: <span class="gi-st"><?= e($sf->t('rs_' . $r['status'])) ?></span> <?= e($sf->t('cond_' . ($rd['condition'] ?? 'ok'))) ?> · <?= e($rd['refund_rub'] ?? '') ?> ₽ · <?= e($rd['reason'] ?? '') ?></p><?php endforeach; ?>
  <p class="muted"><?= e($sf->t('next_steps')) ?>: <?= $next ? e(implode(', ', array_map(fn($s) => $sf->t('st_' . $s), $next))) : '—' ?></p>
  <?php if ($o['status'] === 'ready_for_issue'): ?><p><?= e($sf->t('code_state')) ?>: <?php if ($code): ?><?= !empty($code['used_at']) ? e($sf->t('code_used')) : ((int)$code['expires_at'] < time() ? e($sf->t('code_expired')) : e($sf->t('code_valid_until', ['t' => date('Y-m-d H:i', (int)$code['expires_at'])]))) ?>, <?= e($sf->t('attempts')) ?> <?= (int)$code['attempts'] ?>/5<?php else: ?>—<?php endif; ?></p>
  <form method="post"><?= csrf_field() ?><button class="btn" name="do" value="newcode"><?= e($sf->t('new_code')) ?></button> <small class="muted"><?= e($sf->t('new_code_hint')) ?></small></form><?php endif; ?>
  <?php if ($o['status'] === 'blocked'): ?><form method="post" class="gi-resolve"><?= csrf_field() ?><label class="fld"><span><?= e($sf->t('resolve_note')) ?></span><input name="note" maxlength="300"></label>
    <div class="row"><button class="btn primary" name="do" value="release"><?= e($sf->t('release')) ?></button><button class="btn" name="do" value="return"><?= e($sf->t('send_back')) ?></button></div></form><?php endif; ?></div>
<div class="card flush"><table class="tbl"><thead><tr><th><?= e($sf->t('col_barcode')) ?></th><th><?= e($sf->t('col_name')) ?></th><th><?= e($sf->t('col_qty')) ?></th><th><?= e($sf->t('col_received')) ?></th><th><?= e($sf->t('status')) ?></th></tr></thead><tbody>
<?php foreach ($items as $i): ?><tr><td><code><?= e($i['barcode']) ?></code></td><td><?= e($i['name']) ?></td><td><?= (int)$i['qty'] ?></td><td><?= (int)$i['received_qty'] ?></td><td><span class="gi-is gi-is-<?= e($i['state']) ?>"><?= e($sf->t('is_' . $i['state'])) ?></span></td></tr><?php endforeach; ?></tbody></table></div>
<?php if ($incidents): ?><div class="card"><h3><?= e($sf->t('nav_incidents')) ?></h3><?php foreach ($incidents as $i): ?><p><span class="gi-sev gi-sev-<?= e($i['severity']) ?>"><?= e($sf->t('inc_' . $i['kind'])) ?></span> <?= e($i['status'] === 'open' ? $sf->t('open') : $sf->t('resolved')) ?> <small class="muted"><?= e($i['created_at']) ?></small><br><small class="gi-wrap"><?= e((string)$i['details']) ?></small></p><?php endforeach; ?></div><?php endif; ?>
<div class="card flush"><table class="tbl"><thead><tr><th><?= e($sf->t('date')) ?></th><th><?= e($sf->t('actor')) ?></th><th><?= e($sf->t('event')) ?></th><th><?= e($sf->t('device')) ?></th><th><?= e($sf->t('code_hash')) ?></th></tr></thead><tbody>
<?php foreach ($log as $l): ?><tr><td class="muted"><?= e($l['ts']) ?><?= $l['client_ts'] && $l['client_ts'] !== $l['ts'] ? '<br><small>' . e($sf->t('device_time')) . ' ' . e($l['client_ts']) . '</small>' : '' ?></td><td><?= e($l['actor']) ?></td><td><?= e($l['action']) ?></td><td class="muted"><?= e($l['device_id'] ?? '') ?></td><td class="muted"><code><?= e(substr((string)$l['code_hash'], 0, 10)) ?></code></td></tr><?php endforeach; ?></tbody></table></div>
